#!/usr/bin/env node
"use strict";
// Cyrus Test Flight (R0): boot ONE disposable real Paper server for one Minecraft version, run the checks, tear it
// down, and print a JSON report. Runs on the build host (node-2) as root, under TF_ROOT only.
//
//   node runner.js run <resolved-spec.json>      -> report JSON on stdout (exit 0), busy (75), bad spec (2)
//   node runner.js setup <javaRelease>           -> fetch + verify one pinned JDK (21 or 25), print its path
//
// Safety model (node-2 is a shared build host):
// - one Test Flight at a time: `flock -n` on TF_ROOT/testflight.lock (a second run gets status "busy" at once);
// - the server runs inside a private network namespace (loopback only: no internet, no host ports) as uid/gid 65534
//   with no_new_privs, nice 10, -Xmx<=1g, 2 visible CPUs, an RSS watchdog and a hard wall-clock timeout;
// - processes are only ever killed by exact PID (the java PID we spawned, or a PID whose cmdline carries this run's
//   unique -Dnxeon.testflight.run marker). Never by pattern;
// - the run dir is removed afterwards; downloads (JDKs, Paper jars) are verified by sha256 before use.
// Every check is pass / fail / not_run with evidence. A check never passes unless it ran.

const fs = require("fs");
const path = require("path");
const net = require("net");
const os = require("os");
const crypto = require("crypto");
const { spawn, spawnSync } = require("child_process");
const L = require("./lib.js");
const PT = require("./playtest-lib.js");

const RUNNER_VERSION = "tf-lite-4"; // 2: seeds, collect, RSS per RCON step; 3: ms per RCON step, world.generateStructures; 4: playtest bot
const TF_ROOT = process.env.TF_ROOT || "/tank/nxeon-build/tmp/testflight";
const LOCK = path.join(TF_ROOT, "testflight.lock");
const RUN_UID = 65534;

