};
export function renderVariant(v: SoundVariant, role: SoundRole, load: SourceLoader, ceilingDb = LIMIT_CEILING_DB): RenderedVariant {
  let mix: Mono = new Float64Array(0);
  for (const l of v.layers) {
    let x: Mono;
    if (l.source === "silence") x = new Float64Array(Math.round((l.length ?? 0) * 44100));
    else if (l.source.startsWith("synth:")) x = synth(l.source.slice(6) as SynthPreset, l.length ?? 0.5, l.seed, l.params);
    else x = trim(load(l.source.slice(4)), l.trimStart, l.length ?? undefined);
    x = repitch(x, l.pitch);
    if (l.fadeIn || l.fadeOut) x = fade(x, l.fadeIn, l.fadeOut);
    x = gain(x, l.gain);
    mix = mixAt(mix, x, l.start);

