// Cyrus eval runner (r33): plan, cost estimate, budget cap, resume, scoring, baseline + report, and one end-to-end run
// through the REAL build service (services/modbuilder/server.js) with a fake claude/javac/jar. No model, no network,
// no money. Run: tsx --test test/cyrus-eval-runner.test.ts
import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, spawnSync, type ChildProcess } from "node:child_process";
import { loadEvalSet, loadMatrix, laneOf, assetsRequest, type Lane } from "../lib/cyrus/eval/set";
import { FIRST_RUN, planRun, readJournal, runPlan, type RunDeps } from "../lib/cyrus/eval/run";
import { scoreBuild, qualityOf } from "../lib/cyrus/eval/score";
import { buildBaseline, dryRunText, reportMarkdown } from "../lib/cyrus/eval/report";
import { evalFlight } from "../lib/cyrus/eval/flight";
import { summarize } from "../lib/cyrus/testflight/summary";
import { CHECK_IDS, type TestFlightReport } from "../lib/cyrus/testflight/types";

const ROOT = path.resolve(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const all = loadEvalSet();
const matrix = loadMatrix();
const tmp = () => fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-eval-"));
const count = (l: Lane) => all.filter((p) => laneOf(p) === l).length;
const byKey = (k: string) => all.find((p) => p.key === k)!;

describe("eval set lanes + plan", () => {
  it("has enough prompts for the recommended first run (30 texture, 20 sound, 20 designer, 20 plain)", () => {
    assert.ok(all.length >= 170, `total ${all.length}`);
    for (const [l, n] of Object.entries(FIRST_RUN)) assert.ok(count(l as Lane) >= n!, `${l}: ${count(l as Lane)} < ${n}`);
  });
  it("first-run preset plans 90 builds on 1.21.11 with a cost estimate", () => {
    const p = planRun(all, matrix, { versions: ["1.21.11"], lanes: FIRST_RUN }, { tag: "first1" });
    assert.equal(p.jobs.length, 90);
    assert.ok(p.estimate.low > 0 && p.estimate.high > p.estimate.low);
    assert.equal(new Set(p.jobs.map((j) => j.id)).size, 90, "build ids are unique");
    const t = dryRunText(p, 40);
    assert.match(t, /DRY RUN first1: 90 builds/);
    assert.match(t, /1\.21\.11 texture +30/);
  });
  it("never plans a version the registry cannot build (26.x)", () => {
    const p = planRun(all, matrix, { versions: ["1.21.11", "26.2"], keys: ["s01-heal"] }, { tag: "v26" });
    assert.deepEqual(p.jobs.map((j) => j.job), ["s01-heal@1.21.11"]);
    assert.ok(p.skipped.some((s) => s.version === "26.2" && /not buildable/.test(s.reason)));
  });
  it("asks the service for what the lane needs", () => {
    assert.equal(assetsRequest(byKey("s01-heal")), undefined);
    assert.deepEqual(Object.keys(assetsRequest(byKey("tex-emerald-pick"))!).sort(), ["namespace", "texture"]);
    assert.equal(assetsRequest(byKey("snd-doorbell"))!.sound, true);
    assert.deepEqual(assetsRequest(byKey("des-shop-menu")), { design: true, gameplay: true, namespace: assetsRequest(byKey("des-shop-menu"))!.namespace });
    assert.match(String(assetsRequest(byKey("des-mana-hud"))!.namespace), /^nx_[0-9a-f]{8}$/);
  });
});

describe("scoring", () => {
  const sound = JSON.parse(fs.readFileSync(path.join(SVC, "sound-example.json"), "utf8"));
  it("a refused must-refuse prompt passes; a built one fails", () => {
    const x = byKey("x01-backdoor");
    assert.equal(scoreBuild(x, "other", "1.21.11", { id: "a", status: "failed", errorCode: "refused" }, null).pass, true);
    assert.equal(scoreBuild(x, "other", "1.21.11", { id: "a", status: "succeeded" }, null).stages.refused.status, "fail");
  });
  it("a downgraded texture fails the assets stage; Test Flight not requested is not_run, never a pass", () => {
    const p = byKey("tex-emerald-pick");
    const s = scoreBuild(p, "texture", "1.21.11", { id: "a", status: "succeeded", safety: { verdict: "pass" }, assetResult: { textures: [], downgraded: [{ kind: "texture", name: "emerald_pick", reason: "quality" }] } }, null);
    assert.equal(s.pass, true);
    assert.equal(s.stages.assets.status, "fail");
    assert.equal(s.stages.boot.status, "not_run");
    assert.equal(s.full, false);
    assert.equal(s.verified, false);
  });
  it("measures synth sounds in process and grades textures from the service's quality verdicts", () => {
    const q = qualityOf({ textures: [{ quality: { verdict: "pass" } }, { quality: { verdict: "warn" } }], sounds: [{ spec: sound }] });
    assert.equal(q.textures.n, 2);
    assert.ok(q.sounds.events >= 1 && q.sounds.measured === q.sounds.events, JSON.stringify(q.sounds));
    assert.ok(q.score !== null && q.score > 0 && q.score <= 1);
  });
});

describe("budget cap + resume (fake transport)", () => {
  const plan = planRun(all, matrix, { versions: ["1.21.11"], lanes: { plain: 4 } }, { tag: "bud" });
  const mk = (submitted: string[]): RunDeps => {
    const recs = new Map<string, { id: string; status: string; costUsd: number; safety: { verdict: string } }>();
    return {
      submit: async (b) => { submitted.push(String(b.id)); recs.set(String(b.id), { id: String(b.id), status: "succeeded", costUsd: 0.1, safety: { verdict: "pass" } }); return { status: "queued" }; },
      get: async (id) => recs.get(id) ?? null,
      sleep: async () => {},
    };
  };
  it("stops submitting before the cap, then a rerun with a larger cap resumes without resubmitting", async () => {
    const out = tmp();
    const h = plan.jobs.map((j) => j.estimateUsd[1]);
    const s1: string[] = [];
    const cap = 0.1 + 0.1 + h[2] - 0.001; // two builds at $0.10 real, the third's high estimate no longer fits
    const r1 = await runPlan(plan, mk(s1), { out, budgetUsd: cap, maxInFlight: 1, pollMs: 0 });
    assert.equal(r1.stoppedForBudget, true);
    assert.equal(r1.done.length, 2);
    assert.equal(r1.pending.length, 2);
    const s2: string[] = [];
    const r2 = await runPlan(plan, mk(s2), { out, budgetUsd: 50, pollMs: 0 });
    assert.equal(r2.resumed, 2);
    assert.equal(r2.done.length, 4);
    assert.deepEqual(new Set([...s1, ...s2]).size, 4, "no build submitted twice");
    assert.ok(readJournal(path.join(out, "bud", "journal.jsonl")).some((l) => l.t === "budget_stop"));
    await assert.rejects(runPlan(planRun(all, matrix, { versions: ["1.21.11"], lanes: { plain: 2 } }, { tag: "bud" }), mk([]), { out, budgetUsd: 5, pollMs: 0 }), /different plan/);
  });
});

// ---------------------------------------------------------------- end to end through the real build service
const FAKE_CLAUDE = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2);
const prompt = a[a.indexOf("--") + 1] || "", sys = a[a.indexOf("--system-prompt") + 1] || "";
const H = process.env.HOME, ws = process.cwd();
const w = (rel, t) => { fs.mkdirSync(path.dirname(path.join(ws, rel)), { recursive: true }); fs.writeFileSync(path.join(ws, rel), t); };
const ns = (prompt.match(/reserved namespace is (nx_[a-z0-9]{8})/) || [])[1] || "nx_00000000";
const kind = /ITEM DESIGNER \\(this build/.test(sys) ? "design" : /CUSTOM TEXTURES/.test(sys) ? "texture" : /CUSTOM SOUNDS/.test(sys) ? "sound" : "plain";
fs.appendFileSync(path.join(H, "claude.log"), JSON.stringify({ kind }) + "\\n");
const yml = (n) => w("src/main/resources/plugin.yml", "name: " + n + "\\nversion: 1.0.0\\nmain: dev.nxeon.plugins." + n.toLowerCase() + "." + n + "\\napi-version: '1.21'\\ndescription: x\\nauthor: Nxeon Mod Builder\\n");
const java = (n, body) => w("src/main/java/dev/nxeon/plugins/" + n.toLowerCase() + "/" + n + ".java", "package dev.nxeon.plugins." + n.toLowerCase() + ";\\n\\nimport org.bukkit.plugin.java.JavaPlugin;\\n\\npublic class " + n + " extends JavaPlugin {\\n" + body + "}\\n");
const meta = (n) => w("modbuilder.json", JSON.stringify({ name: n, version: "1.0.0", tagline: n, summary: n + ".", howToUse: ["Install it"] }));
if (kind === "design") {
  meta("StormMod"); yml("StormMod"); java("StormMod", "");
  w("assets/designs/storm_staff.json", fs.readFileSync(path.join(H, "storm_staff.json"), "utf8"));
} else if (kind === "texture") {
  meta("Ruby"); yml("Ruby"); java("Ruby", "  static final String MODEL = \\"" + ns + ":ruby_sword\\";\\n");
  w("assets/textures/ruby_sword.json", fs.readFileSync(path.join(H, "ruby_sword.json"), "utf8"));
} else if (kind === "sound") {
  meta("Banshee"); yml("Banshee"); java("Banshee", "  static final String[] KEYS = { " + ["ambient", "hurt", "death"].map((e) => '"' + ns + ":banshee." + e + '"').join(", ") + " };\\n");
  w("assets/sounds/banshee.json", fs.readFileSync(path.join(H, "sound-example.json"), "utf8"));
} else { meta("Hello"); yml("Hello"); java("Hello", ""); }
const u = { input_tokens: 2, cache_creation_input_tokens: 900, cache_read_input_tokens: 14000, output_tokens: 3000 };
const out = (o) => process.stdout.write(JSON.stringify(o) + "\\n");
out({ type: "system", subtype: "init", model: "claude-sonnet-5-5" });
out({ type: "assistant", message: { id: "m1", usage: u, content: [{ type: "text", text: "Done." }] } });
out({ type: "result", subtype: "success", is_error: false, num_turns: 1, total_cost_usd: 0.05, duration_ms: 900, duration_api_ms: 800, result: "Done.", usage: u });
`;
const FAKE_JAVAC = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2); const d = a[a.indexOf("-d") + 1];
fs.mkdirSync(path.join(d, "dev/nxeon/plugins/x"), { recursive: true }); fs.writeFileSync(path.join(d, "dev/nxeon/plugins/x/X.class"), "x");
`;
const FAKE_JAR = `#!/usr/bin/env node
const fs = require("fs"), path = require("path");
const a = process.argv.slice(2); const file = a[a.indexOf("--file") + 1];
if (a[0] === "--extract") { const j = JSON.parse(fs.readFileSync(file, "utf8")); for (const [k, v] of Object.entries(j)) { fs.mkdirSync(path.dirname(k) === "." ? "." : path.dirname(k), { recursive: true }); fs.writeFileSync(k, Buffer.from(v, "base64")); } process.exit(0); }
const out = {};
const add = (root, rel) => { const abs = path.join(root, rel); if (fs.statSync(abs).isDirectory()) { for (const n of fs.readdirSync(abs)) add(root, rel === "." ? n : rel + "/" + n); } else out[rel] = fs.readFileSync(abs).toString("base64"); };
for (let i = 0; i < a.length; i++) if (a[i] === "-C") { add(a[i + 1], a[i + 2]); i += 2; }
fs.writeFileSync(file, JSON.stringify(Object.fromEntries(Object.entries(out).sort((x, y) => (x[0] < y[0] ? -1 : 1)))));
`;

function yamlStub(): string | null {
  try { require.resolve("yaml", { paths: [SVC] }); return null; } catch { /* use the pipeline test's stub */ }
  const m = /const YAML_STUB = `([\s\S]*?)`;\n/.exec(fs.readFileSync(path.join(ROOT, "test/modbuilder-pipeline.test.ts"), "utf8"));
  return m ? m[1].replace(/\\\\/g, "\\") : null;
}

describe("end to end: real build service + fake CLI, scored, flown (fake Test Flight), baseline + report", () => {
  const KEY = "test-key-0123456789abcdef";
  let dir = "", port = 0, proc: ChildProcess | null = null, err = "";
  before(async () => {
    dir = tmp();
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", "#!/usr/bin/env node\n"]]) fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    fs.copyFileSync(path.join(ROOT, "test/fixtures/cyrus-textures/ruby_sword.json"), path.join(dir, "ruby_sword.json"));
    fs.copyFileSync(path.join(SVC, "sound-example.json"), path.join(dir, "sound-example.json"));
    fs.copyFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/storm_staff.json"), path.join(dir, "storm_staff.json"));
    const nodePath = path.join(dir, "node_modules");
    const stub = yamlStub();
    if (stub) { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), stub); }
    port = 39000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: { PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"), MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_GUARD: "off", NODE_PATH: nodePath } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc.stderr?.on("data", (d) => { err += d; });
    for (let i = 0; i < 100; i++) {
      try { if ((await (await fetch(`http://127.0.0.1:${port}/health`)).json()).ok) return; } catch { /* starting */ }
      await new Promise((r) => setTimeout(r, 100));
    }
    throw new Error(`service did not start: ${err.slice(-1500)}`);
  });
  after(() => { proc?.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("runs plain + texture + sound + designer prompts, scores them and writes an honest baseline", async () => {
    const call = async (m: string, p: string, b?: unknown) => fetch(`http://127.0.0.1:${port}${p}`, { method: m, headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: b === undefined ? undefined : JSON.stringify(b) });
    const plan = planRun(all, matrix, { versions: ["1.21.11"], keys: ["s01-heal", "tex-emerald-pick", "snd-doorbell", "des-storm-staff"] }, { tag: "e2e" });
    const out = tmp();
    let flown = 0;
    const deps: RunDeps = {
      submit: async (b) => (await call("POST", "/builds", b)).json(),
      get: async (id) => { const r = await call("GET", `/builds/${id}`); return r.ok ? r.json() : null; },
      flight: (job, rec) => evalFlight(job.version, rec, {
        jarDir: path.join(out, "jars"),
        artifact: async (id) => Buffer.from(await (await call("GET", `/builds/${id}/artifact`)).arrayBuffer()),
        run: async (spec) => {
          flown++;
          const report = { schema: 1, runId: `tf-${flown}`, status: "completed", version: spec.version, javaRelease: 21, startedAt: "", finishedAt: "", timings: {}, bootMs: 9000, doneReportedSec: 9, peakRssKb: 1, artifacts: [], notes: [], overall: "passed",
            engine: { runner: "tf-lite-4", runnerSha256: "0".repeat(64), paper: { build: 1 }, jdk: { version: "21" } },
            checks: CHECK_IDS.map((id) => ({ id, status: id === "playtest" ? "not_run" : "pass", required: id !== "playtest", evidence: id === "rcon_checks" ? ["plugins: ok"] : ["ok"], durationMs: 1 })) } as unknown as TestFlightReport;
          return { report, summary: summarize(spec, report), resolved: {} as never, stderr: "" };
        },
      }),
      sleep: (ms) => new Promise((r) => setTimeout(r, Math.min(ms, 100))),
    };
    const res = await runPlan(plan, deps, { out, budgetUsd: 20, maxInFlight: 2, pollMs: 50, timeoutMs: 60_000 });
    assert.equal(res.done.length, 4, err.slice(-2000));
    const by = Object.fromEntries(res.done.map((r) => [r.key, r]));
    for (const r of res.done) assert.equal(r.status, "succeeded", `${r.key}: ${r.errorCode} ${JSON.stringify(r.stages)} ${err.slice(-1500)}`);
    assert.equal(by["tex-emerald-pick"].stages.assets.status, "pass", JSON.stringify(by["tex-emerald-pick"].stages));
    assert.ok(by["tex-emerald-pick"].quality.textures.n === 1);
    assert.equal(by["snd-doorbell"].stages.assets.status, "pass", JSON.stringify(by["snd-doorbell"].stages));
    assert.ok(by["snd-doorbell"].quality.sounds.measured >= 1);
    assert.equal(by["des-storm-staff"].stages.assets.status, "pass", JSON.stringify(by["des-storm-staff"].stages));
    assert.equal(by["s01-heal"].stages.assets.status, "n/a");
    for (const r of res.done) { assert.equal(r.stages.boot.status, "pass", JSON.stringify(r.flight)); assert.equal(r.stages.playtest.status, "not_run"); }
    assert.equal(flown, 4);
    const kinds = fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").map((l) => JSON.parse(l).kind).sort();
    assert.deepEqual(kinds, ["design", "plain", "sound", "texture"], "each lane reached the model with its studio section");
    const b = buildBaseline(plan, res.done, { real: false, budgetUsd: 20, spentUsd: res.spentUsd, stoppedForBudget: false, pending: [], service: null });
    assert.equal(b.totals.n, 4);
    assert.equal(b.byLane.texture.n, 1);
    const md = reportMarkdown(b, res.done);
    assert.match(md, /NOT A REAL RUN/);
    assert.match(md, /## By lane/);
    // resume: same plan, nothing new submitted, nothing new flown
    const before = kinds.length;
    const again = await runPlan(plan, deps, { out, budgetUsd: 20, pollMs: 10 });
    assert.equal(again.resumed, 4);
    assert.equal(fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").length, before);
  });

  it("the CLI dry run prints the first-run plan and submits nothing", () => {
    const r = spawnSync(process.execPath, [path.join(ROOT, "node_modules/.bin/tsx"), path.join(ROOT, "scripts/cyrus/eval-run.ts"), "--dry-run", "--preset", "first-run", "--budget", "40"], { encoding: "utf8", cwd: ROOT });
    assert.equal(r.status, 0, r.stderr);
    assert.match(r.stdout, /DRY RUN dry-run: 90 builds/);
    assert.match(r.stdout, /Nothing is submitted/);
  });
});

