describe("end to end: real build service + fake CLI, scored, flown (fake Test Flight), baseline + report", () => {
  const KEY = "test-key-0123456789abcdef";
  let dir = "", port = 0, proc: ChildProcess | null = null, err = "";
  before(async () => {
    dir = tmp();
    const bin = path.join(dir, "bin");
    fs.mkdirSync(bin);
    for (const [n, t] of [["claude", FAKE_CLAUDE], ["javac", FAKE_JAVAC], ["jar", FAKE_JAR], ["javap", "#!/usr/bin/env node\n"]]) fs.writeFileSync(path.join(bin, n), t, { mode: 0o755 });
    const cp = path.join(dir, "cp");
    fs.mkdirSync(cp);
    fs.writeFileSync(path.join(cp, "1.21.11.txt"), "/nonexistent.jar\n");
    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\n");
    fs.writeFileSync(path.join(dir, "claude.log"), "");
    fs.copyFileSync(path.join(ROOT, "test/fixtures/cyrus-textures/ruby_sword.json"), path.join(dir, "ruby_sword.json"));
    fs.copyFileSync(path.join(SVC, "sound-example.json"), path.join(dir, "sound-example.json"));
    fs.copyFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/storm_staff.json"), path.join(dir, "storm_staff.json"));
    const nodePath = path.join(dir, "node_modules");
    const stub = yamlStub();
    if (stub) { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), stub); }
    port = 39000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: { PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"), MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_GUARD: "off", NODE_PATH: nodePath } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc.stderr?.on("data", (d) => { err += d; });
    for (let i = 0; i < 100; i++) {
      try { if ((await (await fetch(`http://127.0.0.1:${port}/health`)).json()).ok) return; } catch { /* starting */ }
      await new Promise((r) => setTimeout(r, 100));
    }
    throw new Error(`service did not start: ${err.slice(-1500)}`);
  });
  after(() => { proc?.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("runs plain + texture + sound + designer prompts, scores them and writes an honest baseline", async () => {
    const call = async (m: string, p: string, b?: unknown) => fetch(`http://127.0.0.1:${port}${p}`, { method: m, headers: { Authorization: `Bearer ${KEY}`, "Content-Type": "application/json" }, body: b === undefined ? undefined : JSON.stringify(b) });
    const plan = planRun(all, matrix, { versions: ["1.21.11"], keys: ["s01-heal", "tex-emerald-pick", "snd-doorbell", "des-storm-staff"] }, { tag: "e2e" });
    const out = tmp();
    let flown = 0;
    const deps: RunDeps = {
      submit: async (b) => (await call("POST", "/builds", b)).json(),
      get: async (id) => { const r = await call("GET", `/builds/${id}`); return r.ok ? r.json() : null; },
      flight: (job, rec) => evalFlight(job.version, rec, {
        jarDir: path.join(out, "jars"),
        artifact: async (id) => Buffer.from(await (await call("GET", `/builds/${id}/artifact`)).arrayBuffer()),
        run: async (spec) => {
          flown++;
          const report = { schema: 1, runId: `tf-${flown}`, status: "completed", version: spec.version, javaRelease: 21, startedAt: "", finishedAt: "", timings: {}, bootMs: 9000, doneReportedSec: 9, peakRssKb: 1, artifacts: [], notes: [], overall: "passed",
            engine: { runner: "tf-lite-4", runnerSha256: "0".repeat(64), paper: { build: 1 }, jdk: { version: "21" } },
            checks: CHECK_IDS.map((id) => ({ id, status: id === "playtest" ? "not_run" : "pass", required: id !== "playtest", evidence: id === "rcon_checks" ? ["plugins: ok"] : ["ok"], durationMs: 1 })) } as unknown as TestFlightReport;
          return { report, summary: summarize(spec, report), resolved: {} as never, stderr: "" };
        },
      }),
      sleep: (ms) => new Promise((r) => setTimeout(r, Math.min(ms, 100))),
    };
    const res = await runPlan(plan, deps, { out, budgetUsd: 20, maxInFlight: 2, pollMs: 50, timeoutMs: 60_000 });
    assert.equal(res.done.length, 4, err.slice(-2000));
    const by = Object.fromEntries(res.done.map((r) => [r.key, r]));
    for (const r of res.done) assert.equal(r.status, "succeeded", `${r.key}: ${r.errorCode} ${JSON.stringify(r.stages)} ${err.slice(-1500)}`);
    assert.equal(by["tex-emerald-pick"].stages.assets.status, "pass", JSON.stringify(by["tex-emerald-pick"].stages));
    assert.ok(by["tex-emerald-pick"].quality.textures.n === 1);
    assert.equal(by["snd-doorbell"].stages.assets.status, "pass", JSON.stringify(by["snd-doorbell"].stages));
    assert.ok(by["snd-doorbell"].quality.sounds.measured >= 1);
    assert.equal(by["des-storm-staff"].stages.assets.status, "pass", JSON.stringify(by["des-storm-staff"].stages));
    assert.equal(by["s01-heal"].stages.assets.status, "n/a");
    for (const r of res.done) { assert.equal(r.stages.boot.status, "pass", JSON.stringify(r.flight)); assert.equal(r.stages.playtest.status, "not_run"); }
    assert.equal(flown, 4);
    const kinds = fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").map((l) => JSON.parse(l).kind).sort();
    assert.deepEqual(kinds, ["design", "plain", "sound", "texture"], "each lane reached the model with its studio section");
    const b = buildBaseline(plan, res.done, { real: false, budgetUsd: 20, spentUsd: res.spentUsd, stoppedForBudget: false, pending: [], service: null });
    assert.equal(b.totals.n, 4);
    assert.equal(b.byLane.texture.n, 1);
    const md = reportMarkdown(b, res.done);
    assert.match(md, /NOT A REAL RUN/);
    assert.match(md, /## By lane/);
    // resume: same plan, nothing new submitted, nothing new flown
    const before = kinds.length;
    const again = await runPlan(plan, deps, { out, budgetUsd: 20, pollMs: 10 });
    assert.equal(again.resumed, 4);
    assert.equal(fs.readFileSync(path.join(dir, "claude.log"), "utf8").trim().split("\n").length, before);
  });

  it("the CLI dry run prints the first-run plan and submits nothing", () => {
    const r = spawnSync(process.execPath, [path.join(ROOT, "node_modules/.bin/tsx"), path.join(ROOT, "scripts/cyrus/eval-run.ts"), "--dry-run", "--preset", "first-run", "--budget", "40"], { encoding: "utf8", cwd: ROOT });
    assert.equal(r.status, 0, r.stderr);
    assert.match(r.stdout, /DRY RUN dry-run: 90 builds/);
    assert.match(r.stdout, /Nothing is submitted/);
  });
});

