const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");

if (require.main === module && process.argv.includes("--print")) {
  const r = compileMod(loadHudFixtures(), { version: "1.21.11", namespace: HUD_NS, pluginName: HUD_PLUGIN });
  if (!r.ok) { console.error(r.errors); process.exit(1); }
  for (const want of process.argv.slice(process.argv.indexOf("--print") + 1)) console.log(`===== ${want}\n${want === "README" ? r.readme : want === "font" ? hudFont(r.huds as HudDesign[], HUD_NS).files.find((f) => f.path
} else if (require.main === module) {
  const out: Record<string, unknown> = {};
  for (const v of VERSIONS.map((x) => x.id).filter((x) => designFeatures(x).ok)) {
    const r = compileMod(loadHudFixtures(), { version: v, namespace: HUD_NS, pluginName: HUD_PLUGIN });
    if (!r.ok) { console.error(v, JSON.stringify(r.errors, null, 1)); process.exit(1); }
    out[v] = { hash: r.hash, readme: r.readmeSha256, files: Object.fromEntries(r.files.map((f) => [f.path.replace(/^src\/main\/java\/dev\/nxeon\/plugins\/hudtrials\//, ""), f.sha256])) };
  }
  const font = hudFont((compileMod(loadHudFixtures(), { version: "1.21.11", namespace: HUD_NS, pluginName: HUD_PLUGIN }) as { huds: HudDesign[] }).huds, HUD_NS);
  out.font = Object.fromEntries(font.files.map((f) => [f.path, sha(f.data)]));
  console.log(JSON.stringify(out, null, 1));
}
