// Cyrus real-client test day: the step catalog, the generated checklist + results form, and the ingest that may flip
// `resourcePackClientVerified` per version ONLY from recorded results (a person with Minecraft Java ran the steps).
// Pure: scripts/cyrus/testday-kit.ts builds the packs/plugins and writes the files; this module decides.
import { createHash } from "node:crypto";

export const TESTDAY_RESULTS_SCHEMA = "cyrus-testday-results-1";
export const TESTDAY_VERSIONS = ["1.21.1", "1.21.4", "1.21.8", "1.21.11"] as const;
export type StepStatus = "untested" | "pass" | "fail" | "skip";

/** What one version's kit contains (written by the kit builder into manifest.json). */
export type KitVersion = {
  version: string; packSha1: string | null; packUrlPath: string | null;
  itemModels: boolean; sounds: string[]; fonts: boolean;
  plugins: { name: string; jar: string | null; command: string | null; readme: string | null; skipped?: string }[];
  /** Exact in-game commands for the pack steps, by step id (vanilla commands, so they test the PACK, not plugin code). */
  commands: Record<string, string[]>;
};
