    const req = STEPS.filter((s) => s.required && stepApplies(s, v));
    const status = (id: string): StepStatus => { const s = steps[id]?.status; return s === "pass" || s === "fail" || s === "skip" ? s : "untested"; };
    const failedSteps = req.filter((s) => status(s.id) === "fail").map((s) => s.id);
    const passed = req.filter((s) => status(s.id) === "pass").length;
    const reasons: string[] = [];
    if (!tester) reasons.push("no tester name");
    if (!dateOk) reasons.push("testedAt is not a date");
    const cv = String(res?.clientVersion ?? "").trim();
    if (cv !== v.version) reasons.push(cv ? `client was ${cv}, not ${v.version}` : "no clientVersion");
    for (const s of req) if (status(s.id) !== "pass") reasons.push(`${s.id}: ${status(s.id)}`);
    const verdict = failedSteps.length && cv === v.version ? "failed" : !reasons.length ? "verified" : "incomplete";
    const pluginSteps = Object.fromEntries(STEPS.filter((s) => !s.required).map((s) => [s.id, status(s.id)]));
