export function applyVerdicts<T extends { versions: { id: string; resourcePackClientVerified: boolean }[] }>(registry: T, verdicts: VersionVerdict[]): { registry: T; changed: string[] } {
  const changed: string[] = [];
  const versions = registry.versions.map((row) => {
    const v = verdicts.find((x) => x.version === row.id);
    if (!v || v.verdict === "incomplete") return row;
    const next = v.verdict === "verified";
    if (next !== row.resourcePackClientVerified) changed.push(`${row.id}: ${row.resourcePackClientVerified} -> ${next}`);
    return { ...row, resourcePackClientVerified: next };
  });
  return { registry: { ...registry, versions }, changed };
}

