        "ctx.head": [`/item replace entity @s armor.head with minecraft:iron_sword[minecraft:item_model="${rubyModel}"]`],
      } : {}),
      ...(itemModels && gunModel ? {
        "states.idle": [`/give @s minecraft:iron_horse_armor[minecraft:item_model="${gunModel}",minecraft:consumable={consume_seconds:72000,animation:"bow",has_consume_particles:false},minecraft:item_name="Pistol"]`],
        "states.reloading": [`/give @s minecraft:iron_horse_armor[minecraft:item_model="${gunModel}",minecraft:custom_model_data={strings:["reloading"]},minecraft:item_name="Pistol (reloading)"]`],
      } : {}),
    };
    kv.push({ version: v, packSha1: p.pack.sha1, packUrlPath: `${v}/pack.zip`, itemModels, sounds: p.pack.sounds.map((s) => s.key), fonts: fonts.length > 0, plugins, commands });
  }
  const kit: Kit = { kitId: kitIdOf(kv), createdAt: new Date().toISOString(), namespace: HUD_NS, versions: kv };
  fs.writeFileSync(path.join(out, "manifest.json"), JSON.stringify(kit, null, 1) + "\n");
  fs.writeFileSync(path.join(out, "CHECKLIST.md"), checklistMarkdown(kit));
  const rf = path.join(out, "results.json");
  if (!fs.existsSync(rf) || JSON.parse(fs.readFileSync(rf, "utf8")).kitId !== kit.kitId) fs.writeFileSync(rf, JSON.stringify(resultsTemplate(kit), null, 1) + "\n");
  for (const l of log) console.log(l);
  for (const v of kv) console.log(`${v.version}: pack ${v.packSha1} (item models ${v.itemModels ? "yes" : "no"}, ${v.sounds.length} sounds, fonts ${v.fonts ? "yes" : "no"}); plugins: ${v.plugins.map((p) => `${p.name}=${p.jar ? "ok" : `skipped (${p.skipped})`}`).join(", ")}`);
  console.log(`kit ${kit.kitId} in ${out}`);
}

function ingest() {
  const kitDir = opt("kit");
  const kit = JSON.parse(fs.readFileSync(path.join(kitDir, "manifest.json"), "utf8")) as Kit;
  const verdicts = ingestResults(JSON.parse(fs.readFileSync(opt("results", path.join(kitDir, "results.json")), "utf8")), kit);
  for (const v of verdicts) console.log(`${v.version}: ${v.verdict} (${v.passed}/${v.required} required steps)${v.reasons.length ? ` - ${v.reasons.slice(0, 6).join("; ")}` : ""}`);
  if (!argv.includes("--apply")) { console.log("(dry: add --apply to write registry.json + client-verify.json in this checkout)"); return; }
  const regFile = path.join(ROOT, "lib/cyrus/versions/registry.json");
  const { registry, changed } = applyVerdicts(JSON.parse(fs.readFileSync(regFile, "utf8")), verdicts);
  fs.writeFileSync(regFile, JSON.stringify(registry, null, 2) + "\n");
  const evFile = path.join(ROOT, "lib/cyrus/versions/client-verify.json");
  const ev = fs.existsSync(evFile) ? JSON.parse(fs.readFileSync(evFile, "utf8")) : { schema: "cyrus-client-verify-1", versions: {} };
  for (const v of verdicts.filter((x) => x.verdict !== "incomplete")) ev.versions[v.version] = { verdict: v.verdict, tester: v.tester, testedAt: v.testedAt, clientVersion: v.clientVersion, kitId: kit.kitId, packSha1: kit.versions.find((k) => k.version === v.version)?.packSha1 ?? null, required: v.required, passed: v.passed, failedSteps: v.failedSteps, pluginSteps: v.pluginSteps };
  fs.writeFileSync(evFile, JSON.stringify(ev, null, 1) + "\n");
  console.log(changed.length ? `registry: ${changed.join(", ")}` : "registry unchanged");
}

const cmd = argv[0];
if (cmd === "build") build();
else if (cmd === "ingest") ingest();
else { console.error("usage: testday-kit.ts build --out DIR [--versions a,b] [--compile] | ingest --kit DIR [--results FILE] [--apply]"); process.exit(2); }

