// Cyrus real-client test day (r33): checklist + results form + ingest rules. The flag flips ONLY from recorded passes
// on a client of exactly that version. Pure. Run: tsx --test test/cyrus-testday.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { applyVerdicts, checklistMarkdown, ingestResults, kitIdOf, resultsTemplate, STEPS, type Kit, type KitVersion } from "../lib/cyrus/eval/testday";

const kv = (version: string, itemModels: boolean): KitVersion => ({
  version, packSha1: "a".repeat(40), packUrlPath: `${version}/pack.zip`, itemModels, sounds: ["nx_r20hud01:banshee.ambient"], fonts: true,
  plugins: [{ name: "VoidArsenal", jar: `${version}/plugins/VoidArsenal.jar`, command: "voidarsenal", readme: "r" }, { name: "GuildQuests", jar: null, command: null, readme: null, skipped: "needs vault-api" }],
  commands: { "snd.play": ["/playsound nx_r20hud01:banshee.ambient master @s"], ...(itemModels ? { "tex.hand": ["/give @s minecraft:iron_sword[minecraft:item_model=\"nx_r20hud01:ruby_sword\"]"] } : {}) },
});
const versions = [kv("1.21.1", false), kv("1.21.11", true)];
const kit: Kit = { kitId: kitIdOf(versions), createdAt: "2026-10-11T00:00:00Z", namespace: "nx_r20hud01", versions };
const passAll = () => {
  const r = resultsTemplate(kit);
  r.tester = "Owner"; r.testedAt = "2026-10-12";
  for (const v of r.results) { v.clientVersion = v.version; for (const s of Object.values(v.steps)) s.status = "pass"; }
  return r;
};
const registry = () => JSON.parse(fs.readFileSync(path.join(__dirname, "..", "lib/cyrus/versions/registry.json"), "utf8"));

describe("test day kit", () => {
  it("the checklist lists every step per version with its command, and marks item-model steps n/a on 1.21.1", () => {
    const md = checklistMarkdown(kit);
    assert.match(md, /## Minecraft 1\.21\.11/);
    assert.match(md, /tex\.hand \| yes \|.*item_model/);
    assert.match(md, /\| tex\.hand \| yes \| n\/a on 1\.21\.1 \|/);
    assert.match(md, /GuildQuests: NOT in this version's kit: needs vault-api/);
    for (const f of ["Resource pack accept prompt", "Textures", "Sounds and subtitles", "Item model states", "Item display contexts", "Menus and quests", "Boss and HUD glyphs", "Motion display entities", "Creature models", "Config reload"]) assert.ok(STEPS.some((s) => s.feature === f), f);
  });
  it("the results form starts untested and only holds steps that apply", () => {
    const r = resultsTemplate(kit);
    assert.ok(Object.values(r.results[0].steps).every((s) => s.status === "untested"));
    assert.ok(!("tex.hand" in r.results[0].steps));
    assert.ok("tex.hand" in r.results[1].steps);
    assert.ok(!("plugin.menus" in r.results[1].steps), "a skipped plugin has no steps");
  });
});

describe("ingest", () => {
  it("all required steps passed on the exact client version -> verified", () => {
    const v = ingestResults(passAll(), kit);
    assert.deepEqual(v.map((x) => x.verdict), ["verified", "verified"]);
    assert.ok(v[0].required < v[1].required, "1.21.1 has no item model steps");
  });
  it("an untouched form, a wrong client version or a missing tester never verifies", () => {
    assert.deepEqual(ingestResults(resultsTemplate(kit), kit).map((x) => x.verdict), ["incomplete", "incomplete"]);
    const r = passAll(); r.results[1].clientVersion = "1.21.10";
    assert.equal(ingestResults(r, kit)[1].verdict, "incomplete");
    const t = passAll(); t.tester = "";
    assert.equal(ingestResults(t, kit)[0].verdict, "incomplete");
    const s = passAll(); (s.results[1].steps as Record<string, { status: string }>)["states.aiming"].status = "skip";
    assert.equal(ingestResults(s, kit)[1].verdict, "incomplete", "a skipped required step is not a pass");
  });
  it("a failed required step -> failed; a failed plugin step is recorded but does not decide the flag", () => {
    const r = passAll(); (r.results[1].steps as Record<string, { status: string }>)["snd.subtitle"].status = "fail";
    const v = ingestResults(r, kit)[1];
    assert.equal(v.verdict, "failed");
    assert.deepEqual(v.failedSteps, ["snd.subtitle"]);
    const p = passAll(); (p.results[1].steps as Record<string, { status: string }>)["plugin.items"].status = "fail";
    const w = ingestResults(p, kit)[1];
    assert.equal(w.verdict, "verified");
    assert.equal(w.pluginSteps["plugin.items"], "fail");
  });
  it("rejects a form for another kit or schema", () => {
    assert.throws(() => ingestResults({ ...passAll(), kitId: "other" }, kit), /kit/);
    assert.throws(() => ingestResults({ ...passAll(), schema: "x" }, kit), /schema/);
  });
  it("applies only verified/failed verdicts to the registry rows", () => {
    const reg = registry();
    const r = passAll(); r.results[0].clientVersion = "";
    const { registry: next, changed } = applyVerdicts(reg, ingestResults(r, kit));
    assert.deepEqual(changed, ["1.21.11: false -> true"]);
    assert.equal(next.versions.find((x: { id: string }) => x.id === "1.21.1").resourcePackClientVerified, false);
    assert.equal(reg.versions.find((x: { id: string }) => x.id === "1.21.11").resourcePackClientVerified, false, "the input is not mutated");
  });
  it("the committed registry is still unverified everywhere (only a real test day changes that)", () => {
    for (const v of registry().versions) assert.equal(v.resourcePackClientVerified, false, v.id);
  });
});

