// Cyrus public pass-rate page + evidence badges (R2 plan item 16), pure half. Every number comes from a RECORDED run:
// an accepted eval baseline (real=true, written by scripts/cyrus/eval-run.ts) and the Test Flight gate records stored
// on builds. Nothing is estimated; no data = an honest empty state, never a placeholder number.
import { passRates, type PassRateRow } from "../delivery/admin";
import { readStoredFlight } from "../testflight/gate";
import { BASELINE_SCHEMA, type Baseline } from "./report";

export const MIN_PUBLISH_N = 10;

export type PassRateView = {
  eval: null | { tag: string; createdAt: string; model: string; builds: number; rows: { version: string; builds: number; finalPassPct: number | null; fullPassPct: number | null; bootPassPct: number | null; booted: number; flown: number }[]; lanes: { lane: string; builds: number; fullPassPct: number | null }[] };
  flights: (PassRateRow & { publishable: boolean })[];
  client: { version: string; verdict: string; testedAt: string }[];
  empty: boolean;
};

/** Only an accepted real baseline counts; a fixture/test baseline (real=false) or another schema is ignored. */
export function acceptedBaseline(raw: unknown): Baseline | null {
  const b = raw as Baseline | null;
  return b && b.schema === BASELINE_SCHEMA && b.real === true && b.totals?.n > 0 ? b : null;
}

export function passRateView(input: { baseline: unknown; cyrusMeta: unknown[]; clientVerify: unknown }): PassRateView {
  const b = acceptedBaseline(input.baseline);
  const flights = passRates(input.cyrusMeta.flatMap((c) => {
    const f = readStoredFlight((c as { testFlight?: unknown } | null)?.testFlight);
    return f ? [{ version: f.version, state: f.state, verdict: f.verdict }] : [];
  })).map((r) => ({ ...r, publishable: r.flown >= MIN_PUBLISH_N }));
  const cv = (input.clientVerify as { versions?: Record<string, { verdict?: string; testedAt?: string }> } | null)?.versions ?? {};
  const client = Object.entries(cv).filter(([, v]) => v?.verdict === "verified" && typeof v.testedAt === "string").map(([version, v]) => ({ version, verdict: v.verdict!, testedAt: v.testedAt! }));
  const ev = b ? {
    tag: b.tag, createdAt: b.createdAt, model: b.model, builds: b.totals.n,
    rows: Object.entries(b.byVersion).map(([version, a]) => ({ version, builds: a.n, finalPassPct: a.finalPassPct, fullPassPct: a.fullPassPct, bootPassPct: a.bootPassPct, booted: a.booted, flown: a.flown })),
    lanes: Object.entries(b.byLane).map(([lane, a]) => ({ lane, builds: a.n, fullPassPct: a.fullPassPct })),
  } : null;
  return { eval: ev, flights, client, empty: !ev && !flights.some((f) => f.flown > 0) && !client.length };
}

export type EvidenceBadge = { id: "boot" | "scan" | "client" | "sbom"; label: string; detail: string };

/** Per-build evidence badges, each only when its record exists (a mod page passes the build's meta + result). */
export function evidenceBadges(cyrusMeta: unknown, result: unknown, clientVerify: unknown, mcVersion: string): EvidenceBadge[] {
  const out: EvidenceBadge[] = [];
  const f = readStoredFlight((cyrusMeta as { testFlight?: unknown } | null)?.testFlight);
  if (f && f.state === "done" && f.verdict === "passed" && f.label) out.push({ id: "boot", label: f.label, detail: `Test Flight ${f.runId ?? ""}${f.engine?.paperBuild ? `, Paper build ${f.engine.paperBuild}` : ""}, ${f.at.slice(0, 10)}`.trim() });
  const r = result as { safety?: { verdict?: string } | null; jar?: { sha256?: string } | null } | null;
  if (r?.safety?.verdict === "pass" || r?.safety?.verdict === "warn") out.push({ id: "scan", label: r.safety.verdict === "pass" ? "safety scan passed" : "safety scan passed with notes", detail: r.jar?.sha256 ? `jar sha256 ${r.jar.sha256.slice(0, 16)}…` : "" });
  const cv = (clientVerify as { versions?: Record<string, { verdict?: string; testedAt?: string }> } | null)?.versions?.[mcVersion];
  if (cv?.verdict === "verified") out.push({ id: "client", label: `resource pack client-tested on Minecraft ${mcVersion}`, detail: `real client, ${String(cv.testedAt).slice(0, 10)}` });
  return out;
}

