import { EVAL_DIR } from "./set";

export const PASSRATE_FLAG = "cyrus_passrate_enabled";
export const PASSRATE_PATH = "/mods/cyrus/pass-rates";
/** The accepted baseline (copied here by the owner after a real run; see docs/CYRUS-EVAL.md). */
export const BASELINE_FILE = path.join(EVAL_DIR, "baseline.json");
export const CLIENT_VERIFY_FILE = path.join(__dirname, "..", "versions", "client-verify.json");

export async function passRateEnabled(): Promise<boolean> {
  try { return await getHost().settings.getBool(PASSRATE_FLAG, false); } catch { return false; }
}

const readJson = (f: string): unknown => { try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return null; } };

let cache: { at: number; view: PassRateView } | null = null;

export async function loadPassRateView(opts: { now?: number } = {}): Promise<PassRateView> {
  const now = opts.now ?? Date.now();
  if (cache && now - cache.at < 10 * 60_000) return cache.view;
  let metas: unknown[] = [];
  try {
    const rows = await cyrusDb.modBuild.findMany({ where: { status: "succeeded" }, orderBy: { finishedAt: "desc" }, take: 5000, select: { cyrus: true } });
