14	export const CLIENT_VERIFY_FILE = () => path.join(process.cwd(), "lib/cyrus/versions/client-verify.json");
15	
16	export async function passRateEnabled(): Promise<boolean> {
17	  try { return await getHost().settings.getBool(PASSRATE_FLAG, false); } catch { return false; }
18	}
