20	const readJson = (f: string): unknown => { try { return JSON.parse(fs.readFileSync(f, "utf8")); } catch { return null; } };
21	
22	let cache: { at: number; view: PassRateView } | null = null;
...
24	export async function loadPassRateView(opts: { now?: number } = {}): Promise<PassRateView> {
25	  const now = opts.now ?? Date.now();
26	  if (cache && now - cache.at < 10 * 60_000) return cache.view;
27	  let metas: unknown[] = [];
28	  try {
29	    const rows = await cyrusDb.modBuild.findMany({ where: { status: "succeeded" }, orderBy: { finishedAt: "desc" }, take: 5000, select: { cyrus: true } });
30	    metas = rows.map((r: { cyrus: unknown }) => r.cyrus);
31	  } catch { metas = []; }
32	  const view = passRateView({ baseline: readJson(BASELINE_FILE()), cyrusMeta: metas, clientVerify: readJson(CLIENT_VERIFY_FILE()) });
33	  cache = { at: now, view };
