// Cyrus public pass rates (/mods/cyrus/pass-rates). Server component, no client JS. Shows only recorded numbers
// (lib/cyrus/eval/passrate.ts); an empty source says so plainly.
import type { EvidenceBadge, PassRateView } from "@/lib/cyrus/eval/passrate";
import { MIN_PUBLISH_N } from "@/lib/cyrus/eval/passrate";

const pct = (v: number | null) => (v === null ? "–" : `${v}%`);
const LANE: Record<string, string> = { plain: "Plain plugins", texture: "Textures", sound: "Sounds", designer: "Designer", datapack: "Data packs", other: "Other" };

export function EvidenceBadgeChip({ b }: { b: EvidenceBadge }) {
  const tone = b.id === "boot" ? "border-emerald-400/40 text-emerald-300" : b.id === "client" ? "border-cyan-400/40 text-cyan-300" : "border-violet/40 text-violet";
  return (
    <span title={b.detail} className={`inline-flex items-center gap-1.5 rounded-full border bg-well px-2.5 py-1 text-[12px] font-semibold ${tone}`}>
      <span aria-hidden className="h-1.5 w-1.5 rounded-full bg-current" />
      {b.label}
    </span>
  );
}

function Card({ title, sub, children }: { title: string; sub?: string; children: React.ReactNode }) {
  return (
    <section className="rounded-[16px] border border-rim-hi bg-surface p-4 sm:p-5">
      <h2 className="text-[15px] font-extrabold text-tx">{title}</h2>
      {sub ? <p className="mt-1 text-[12.5px] leading-relaxed text-tx-dim">{sub}</p> : null}
      <div className="mt-3">{children}</div>
    </section>
  );
}

function Empty({ children }: { children: React.ReactNode }) {
  return <p className="rounded-[12px] border border-dashed border-rim-hi bg-well px-3 py-3 text-[13px] text-tx-dim">{children}</p>;
}

function Table({ head, rows }: { head: string[]; rows: (string | number)[][] }) {
  return (
    <div className="-mx-1 overflow-x-auto">
      <table className="w-full min-w-[420px] text-left text-[13px]">
        <thead><tr className="text-[11px] uppercase tracking-wide text-tx-faint">{head.map((h) => <th key={h} className="px-1 py-1.5 font-bold">{h}</th>)}</tr></thead>
        <tbody>{rows.map((r, i) => <tr key={i} className="border-t border-rim-hi">{r.map((c, j) => <td key={j} className={`num px-1 py-2 ${j === 0 ? "font-bold text-tx" : "text-tx-body"}`}>{c}</td>)}</tr>)}</tbody>
      </table>
    </div>
  );
}

export function PassRates({ v, sample = false }: { v: PassRateView; sample?: boolean }) {
  const flown = v.flights.filter((f) => f.flown > 0);
  return (
    <div className="flex flex-col gap-5">
      <header className="nx-dark-island relative overflow-hidden rounded-[20px] border border-[#7b3fef]/35 bg-[radial-gradient(110%_140%_at_100%_0%,rgba(140,58,233,.34),transparent_55%),linear-gradient(160deg,#071434,#020817)] px-5 py-7 sm:px-8">
        <h1 className="text-[26px] font-extrabold tracking-[-0.025em] text-white sm:text-[30px]">Cyrus pass rates</h1>
        <p className="mt-1.5 max-w-[68ch] text-[13.5px] leading-relaxed text-white/75">
          How often Cyrus builds a mod that works, measured, never estimated. Numbers come only from recorded runs: our evaluation set built through the real build service, and the Test Flight that boots every build on a real Paper server of the exact version.
        </p>
        {sample ? <p className="mt-3 inline-flex rounded-full border border-amber-300/40 bg-amber-300/10 px-3 py-1 text-[11px] font-bold uppercase tracking-wide text-amber-200">Sample data for a screenshot, not a real run</p> : null}
      </header>

      {v.empty ? (
        <Card title="No measured results yet" sub="We publish a number here only after we have measured it.">
          <Empty>The first evaluation run and the first Test Flight results will appear here once they are recorded. Until then there is nothing to show, on purpose.</Empty>
        </Card>
      ) : null}

      <div className="grid gap-4 lg:grid-cols-2">
        <Card title="Evaluation set" sub={v.eval ? `Run ${v.eval.tag}, ${v.eval.createdAt.slice(0, 10)}, ${v.eval.builds} builds. Full pass = it built, passed the safety scan and every check that ran (assets, quality, boot).` : "Fixed prompts, built through the real build service and scored stage by stage."}>
          {v.eval ? (
            <Table head={["Minecraft", "Builds", "Built", "Full pass", "Boot-tested"]} rows={v.eval.rows.map((r) => [r.version, r.builds, pct(r.finalPassPct), pct(r.fullPassPct), r.flown ? `${pct(r.bootPassPct)} (${r.booted}/${r.flown})` : "not flown"])} />
          ) : <Empty>No accepted evaluation run yet.</Empty>}
        </Card>
        <Card title="Test Flight on real servers" sub={`Builds booted on a real Paper server of the exact version. A version shows a rate once ${MIN_PUBLISH_N} builds have flown.`}>
          {flown.length ? (
            <Table head={["Paper", "Flown", "Passed", "Failed", "Pass rate"]} rows={flown.map((f) => [f.version, f.flown, f.passed, f.failed, f.publishable && f.passRate !== null ? `${Math.round(f.passRate * 1000) / 10}%` : `needs ${MIN_PUBLISH_N}`])} />
          ) : <Empty>No Test Flight results recorded yet.</Empty>}
        </Card>
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <Card title="By kind of mod" sub="Full pass rate per lane of the evaluation set.">
          {v.eval?.lanes.length ? (
            <ul className="flex flex-col gap-2">
              {v.eval.lanes.map((l) => (
                <li key={l.lane} className="flex items-center gap-3 text-[13px]">
                  <span className="w-[110px] flex-none font-bold text-tx">{LANE[l.lane] ?? l.lane}</span>
                  <span className="relative h-2 flex-1 overflow-hidden rounded-full bg-well"><span className="absolute inset-y-0 left-0 rounded-full bg-violet" style={{ width: `${l.fullPassPct ?? 0}%` }} /></span>
                  <span className="num w-[86px] flex-none text-right text-tx-dim">{pct(l.fullPassPct)} of {l.builds}</span>
                </li>
              ))}
            </ul>
          ) : <Empty>Appears with the first evaluation run.</Empty>}
        </Card>
        <Card title="Resource packs in a real client" sub="Textures, sounds, item models and HUD glyphs checked by a person in Minecraft Java, version by version.">
          {v.client.length ? (
            <div className="flex flex-wrap gap-1.5">{v.client.map((c) => <EvidenceBadgeChip key={c.version} b={{ id: "client", label: `client-tested on ${c.version}`, detail: c.testedAt }} />)}</div>
          ) : <Empty>Not client-tested on any version yet.</Empty>}
        </Card>
      </div>

      <Card title="Evidence badges on mods" sub="Each badge appears on a mod only when its record exists.">
        <div className="flex flex-wrap gap-1.5">
          <EvidenceBadgeChip b={{ id: "boot", label: "boot-tested on Paper <exact version>", detail: "a Test Flight passed every required check" }} />
          <EvidenceBadgeChip b={{ id: "scan", label: "safety scan passed", detail: "with the jar's sha256" }} />
          <EvidenceBadgeChip b={{ id: "client", label: "resource pack client-tested on <version>", detail: "a real client test day" }} />
        </div>
        <p className="mt-3 text-[12px] text-tx-faint">Boot-tested means the server started with the mod enabled and its commands registered. It does not promise every in-game behaviour.</p>
      </Card>
    </div>
  );
}

