import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { requireCyrusAccess, cyrusMetadata } from "@/lib/cyrus-mods/gate";
import { loadPassRateView, passRateEnabled } from "@/lib/cyrus/eval/passrate-data";
import { samplePassRateView } from "@/lib/cyrus/eval/passrate";
import { PassRates } from "@/components/nx/labs/cyrus/PassRates";

export const dynamic = "force-dynamic";

export async function generateMetadata(): Promise<Metadata> {
  const m = await cyrusMetadata("Cyrus pass rates · NxLabs", "Measured build, scan and boot-test pass rates for Cyrus, Nxeon's AI mod studio.");
  return { ...m, robots: { index: false, follow: true } };
}

/** Public pass rates. 404 unless Setting cyrus_passrate_enabled AND the Cyrus mods gate allow it (preview accounts see it
 *  before both). Numbers only from recorded runs (lib/cyrus/eval/passrate.ts). */
