  const { access } = await requireCyrusAccess();
  if (!access.preview && !(await passRateEnabled())) notFound();
  const sample = process.env.NODE_ENV !== "production" && process.env.CYRUS_PASSRATE_SAMPLE === "1";
  const v = sample ? samplePassRateView() : await loadPassRateView();
  return (
    <div className="mx-auto w-full max-w-[1240px] px-4 py-8 sm:px-6 sm:py-10">
      <PassRates v={v} sample={sample} />
    </div>
  );
}
