// Run: tsx --test test/cyrus-passrate.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { acceptedBaseline, evidenceBadges, MIN_PUBLISH_N, passRateView } from "../lib/cyrus/eval/passrate";
import { BASELINE_SCHEMA } from "../lib/cyrus/eval/report";

const ROOT = path.join(__dirname, "..");
const read = (f: string) => fs.readFileSync(path.join(ROOT, f), "utf8");
const flight = (version: string, verdict: string, state = "done") => ({ testFlight: { schema: 1, gate: "tfgate-1", state, version, verdict, label: verdict === "passed" ? `boot-tested on Paper ${version}` : null, checks: [], flights: 1, busyRetries: 0, runId: "tf-1", engine: { paperBuild: 12 }, at: "2026-10-11T00:00:00Z" } });
