// Cyrus r33 screenshots of /mods/cyrus/pass-rates (run ON node-2 against `devhost dev`, flags on in the throwaway DB).
//   devhost run -- node scripts/cyrus/passrate-shots.mjs   (env: BASE, OUT, PREFIX = passrate-empty | passrate-sample)
import { createRequire } from "node:module";
import { mkdirSync } from "node:fs";
const require = createRequire(import.meta.url);
const { chromium } = require("playwright");
const BASE = process.env.BASE ?? "http://127.0.0.1:4444";
const OUT = process.env.OUT ?? ".shots";
const PREFIX = process.env.PREFIX ?? "passrate";
mkdirSync(OUT, { recursive: true });
const browser = await chromium.launch();
for (const [name, theme, view] of [["dark", "dark", { width: 1440, height: 900 }], ["light", "light", { width: 1440, height: 900 }], ["phone", "dark", { width: 390, height: 844, mobile: true }]]) {
  const ctx = await browser.newContext({ viewport: { width: view.width, height: view.height }, isMobile: !!view.mobile, hasTouch: !!view.mobile, colorScheme: theme });
  await ctx.addCookies([{ name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); } catch {} if (t === "light") document.addEventListener("DOMContentLoaded", () => document.documentElement.setAttribute("data-theme", "light")); }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 200)));
  const r = await page.goto(BASE + "/mods/cyrus/pass-rates", { waitUntil: "load", timeout: 300000 }).catch((e) => { errs.push("goto " + e); return null; });
  await page.waitForSelector("h1", { timeout: 120000 }).catch(() => errs.push("no h1"));
  await page.waitForTimeout(1500);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  await page.screenshot({ path: `${OUT}/${PREFIX}-${name}.png`, fullPage: true });
  console.log(`${PREFIX}-${name}.png status=${r?.status()}`, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.join(" | "));
  await ctx.close();
}
await browser.close();
EOF
